INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2707263', 'Third Battle of Tapae', 'The Third Battle of Tapae (101) was the decisive battle of the first of Trajan''s Dacian Wars, in which the Roman Emperor defeated the Dacian King Decebalus''s army. Other setbacks in the campaign delayed its completion until 102.', 101, 9, NULL, NULL, NULL, NULL, 'month', 'September 101', 52, 'https://en.wikipedia.org/wiki/Third_Battle_of_Tapae'),
  ('Q2887810', 'Battle of Adamclisi', 'The Battle of Adamclisi was a major clash during the Dacian Wars, fought in the winter of 101 to 102 between the Roman Empire and the Dacians near Adamclisi, in modern Romania.', 101, NULL, NULL, 102, NULL, NULL, 'year', '101–102', 43, 'https://en.wikipedia.org/wiki/Battle_of_Adamclisi'),
  ('Q3494883', 'Battle of Sarmisegetusa', 'The Battle of Sarmizegetusa (also spelled Sarmizegethuza) was a siege of Sarmizegetusa, the capital of Dacia, fought in Trajan''s Second Dacian War in 106 between the army of the Roman Emperor Trajan, and the Dacians led by King Decebalus.', 106, NULL, NULL, NULL, NULL, NULL, 'year', '106', 48, 'https://en.wikipedia.org/wiki/Battle_of_Sarmizegetusa'),
  ('Q872007', 'Battle of Kerlés', 'The Battle of Kerlés (Hungarian: kerlési csata) also known as the Battle of Cserhalom (Hungarian: cserhalmi csata), was an engagement between an army of Pechenegs and Ouzes commanded by Osul and the troops of King Solomon of Hungary and his cousins, Dukes Géza and Ladislaus, in Transylvania in 1068. The Pechenegs had been the dominant power of the westernmost regions of the Eurasian steppes since around 895.', 1068, NULL, NULL, NULL, NULL, NULL, 'year', '1068', 45, 'https://en.wikipedia.org/wiki/Battle_of_Kerl%C3%A9s'),
  ('Q1076246', 'Battle of Posada', 'The Battle of Posada (9–12 November 1330) was fought between Basarab I of Wallachia and Charles I of Hungary (also known as Charles Robert). The small Wallachian army led by Basarab, formed of cavalry and foot archers, as well as local peasants, managed to ambush and defeat the 30,000-strong Hungarian army, in a mountainous region.', 1330, 11, 9, 1330, 11, 12, 'day', '9 November 1330 – 12 November 1330', 57, 'https://en.wikipedia.org/wiki/Battle_of_Posada'),
  ('Q1073358', 'Battle of Vaslui', 'The Battle of Vaslui (also referred to as the Battle of Podul Înalt or the Battle of Racova) was a battle that was fought on 10 January 1475, between Stephen III of Moldavia and the Ottoman governor of Rumelia, Hadım Suleiman Pasha. The battle took place at Podul Înalt ("the High Bridge"), near the town of Vaslui, in Moldavia (now part of eastern Romania).', 1475, 1, 10, NULL, NULL, NULL, 'day', '10 January 1475', 60, 'https://en.wikipedia.org/wiki/Battle_of_Vaslui'),
  ('Q2533670', 'Battle of Valea Albă', 'The Battle of Valea Albă, also known as the Battle of Războieni or the Battle of Akdere, was an important event in the medieval history of Moldavia. It took place at Războieni, also known as Valea Albă, on 26 July 1476, between the Moldavian army of Stephen the Great and an invading Ottoman army which was commanded personally by Sultan Mehmed the Conqueror.', 1476, 7, 26, NULL, NULL, NULL, 'day', '26 July 1476', 51, 'https://en.wikipedia.org/wiki/Battle_of_Valea_Alb%C4%83'),
  ('Q690291', 'Battle of Breadfield', 'The Battle of Breadfield (Hungarian: Kenyérmezei csata, German: Schlacht auf dem Brodfeld, Romanian: Bătălia de la Câmpul Pâinii, Turkish: Ekmek Otlak Savaşı) was the most tremendous conflict fought in Transylvania up to that time in the Ottoman–Hungarian Wars, taking place on 13 October 1479, on the Breadfield near the Saxon village of Alkenyér (also Zsibód, German: Unterbrodsdorf, Romanian: Șibot) next to the river Maros (Mureș). The Hungarian army was led by Pál Kinizsi, István Báthory, Vuk Branković, and Basarab Laiotă cel Bătrân.', 1479, 10, 13, NULL, NULL, NULL, 'day', '13 October 1479', 60, 'https://en.wikipedia.org/wiki/Battle_of_Breadfield'),
  ('Q1317918', 'Siege of Temesvár', 'The siege of Temesvár was a military conflict between the Habsburg monarchy and the Ottoman Empire in 1552. The siege resulted with a decisive Ottoman victory and Temesvár came under Ottoman control for 164 years.', 1552, NULL, NULL, 1552, 7, 6, 'year', '1552', 47, 'https://en.wikipedia.org/wiki/Siege_of_Temesv%C3%A1r_(1552)'),
  ('Q2540658', 'Battle of Călugăreni', 'The Battle of Călugăreni took place during the history of early modern Romania on 23 August [O.S. 13 August] 1595 between the Wallachian army led by Michael the Brave and the Ottoman army led by Koca Sinan Pasha. It was part of the Long Turkish War, fought between Christian and Ottoman forces at the end of the 16th and the beginning of the 17th centuries.', 1595, 8, 23, NULL, NULL, NULL, 'day', '23 August 1595', 51, 'https://en.wikipedia.org/wiki/Battle_of_C%C4%83lug%C4%83reni'),
  ('Q12723161', 'Battle of Giurgiu (1595)', 'The Battle of Giurgiu, also known as the Bridge Disaster (Turkish: Köprü Faciası), took place on 27–30 October 1595. It was part of the Long Turkish War (1593–1606), a border conflict between the Christian powers and the Ottoman Empire over Balkan territories.', 1595, 10, 27, 1595, 10, 30, 'day', '27 October 1595 – 30 October 1595', 43, 'https://en.wikipedia.org/wiki/Battle_of_Giurgiu_(1595)'),
  ('Q592069', 'Battle of Sellenberk', 'The Battle of Șelimbăr, or Battle of Sellenberk (Hungarian: Sellenberk; German: Schellenberg), took place on 18 October 1599 between the Wallachian army of Michael the Brave (Romanian: Mihai Viteazul) and the Transylvanian-Hungarian army of Andrew Báthory (Hungarian: Báthory András). The battle was fought near the village of Șelimbăr (Hungarian: Sellenberk) close to Sibiu (German: Hermannstadt; Hungarian: Nagyszeben).', 1599, 10, 28, NULL, NULL, NULL, 'day', '28 October 1599', 48, 'https://en.wikipedia.org/wiki/Battle_of_%C8%98elimb%C4%83r'),
  ('Q722205', 'Battle of Mirăslău', 'The Battle of Mirăslău, or Battle of Miriszló, took place on September 18, 1600, near Miriszló (Romanian: Mirăslău), Transylvania, between the Wallachian troops led by Michael the Brave supported by ethnic Hungarian Szeklers and the troops of Austrian general Giorgio Basta supported by the Hungarian nobility of Transylvania. In 1599, Michael took control of Transylvania after the Battle of Șelimbăr.', 1600, 9, 18, NULL, NULL, NULL, 'day', '18 September 1600', 41, 'https://en.wikipedia.org/wiki/Battle_of_Mir%C4%83sl%C4%83u'),
  ('Q2576318', 'Battle of Finta', 'The Battle of Finta (27 May 1653) was a confrontation between Prince Matei Basarab''s Wallachian army and a combined Moldavian–Cossack–Tatar force under Prince Vasile Lupu and Tymofiy Khmelnytsky. It took place around Finta, now a commune in Dâmbovița County, Romania.', 1653, 5, 27, NULL, NULL, NULL, 'day', '27 May 1653', 45, 'https://en.wikipedia.org/wiki/Battle_of_Finta'),
  ('Q4872808', 'Battle of Zernest', 'The Battle of Zernest was fought on 11 August 1690, near the town of Zernest (Zărnești) in southeastern Transylvania (today in Romania), between the allied forces of Transylvania and the Holy Roman Empire, and the forces of the Ottoman Empire and their vassals, the Crimean Tatars and Wallachians, and the allied Hungarian Kurucs.', 1690, 8, 11, NULL, NULL, NULL, 'day', '11 August 1690', 41, 'https://en.wikipedia.org/wiki/Battle_of_Zernest'),
  ('Q2309898', 'Battle of Karánsebes', 'The Battle of Karánsebes (Turkish: Şebeş Muharebesi; German: Rückzug von Karánsebes; Hungarian: Karánsebesi csata; Romanian: Bătălia de la Caransebeș) was a friendly fire incident in the Austrian army, occurring during the night of 21–22 September 1788, during the Austro-Turkish War of 1788–1791. Some historians have referred to the battle as "history''s worst friendly fire incident".', 1788, 9, 21, NULL, NULL, NULL, 'day', '21 September 1788', 64, 'https://en.wikipedia.org/wiki/Battle_of_Kar%C3%A1nsebes'),
  ('Q1025134', 'Battle of Focșani', 'The Battle of Focșani (also Battle of Fokschani or Battle of Focsani; Hungarian: Foksányi csata) took place during the Russo-Turkish War (1787–1792) on 1 August 1789 (Old Style 21 July) between the Ottoman Empire and the alliance of the Russian Empire and the Habsburg monarchy near Focșani, Moldavia (now in Romania). The Russians were led by Alexander Suvorov, the Austrians by Prince Josias of Coburg, and the Ottomans by Grand Vizier Koca Yusuf Pasha.', 1789, 8, 1, NULL, NULL, NULL, 'day', '1 August 1789', 53, 'https://en.wikipedia.org/wiki/Battle_of_Foc%C8%99ani'),
  ('Q2234632', 'Battle of Rymnik', 'The Battle of Rymnik or Rimnik, also Battle of Mărtinești (Turkish: Boze Savaşı [Battle of the Boze]; Russian: Рымникское сражение [Battle of the Rymnik]; German: Schlacht am Rimnik), on September 22 [O.S. September 11] 1789, took place in Wallachia, at the Râmnicul Sărat River, known as the Rymnik, near Râmnicu Sărat or Rymnik (now in Romania) during the Russo-Turkish War of 1787–1792 and the Austro-Turkish War of 1788–1791. The Russian general Alexander Suvorov, acting together with the Habsburg general Prince Josias of Coburg, attacked the main Ottoman army under Grand Vizier Cenaze…', 1789, 9, 22, NULL, NULL, NULL, 'day', '22 September 1789', 61, 'https://en.wikipedia.org/wiki/Battle_of_Rymnik'),
  ('Q2897258', 'Battle of Măcin', 'The Battle of Măcin took place during the Russo-Turkish War (1787–1792), fought on 9 July 1791 between the Ottoman Empire and the Russian Empire. The Russian army of 30,000 was commanded by Prince Nicholas Repnin, whereas the Turks, numbering about 80,000 men, were led by Koca Yusuf Pasha.', 1791, 7, 10, NULL, NULL, NULL, 'day', '10 July 1791', 43, 'https://en.wikipedia.org/wiki/Battle_of_M%C4%83cin'),
  ('Q4896386', 'Bessarabian question', 'The Bessarabian question, Bessarabian issue or Bessarabian problem (Romanian: Problema basarabeană or chestiunea basarabeană; Russian: Бессарабский вопрос or бессарабская проблема; Ukrainian: Бессарабське питання or Бессарабська проблема) is the name given to the controversy over the ownership of the geographic region of Bessarabia that began with the annexation of the region by the Russian Empire from the Romanian principality of Moldavia in 1812 through the Treaty of Bucharest and which continued with the independence and union of Bessarabia with Romania in 1917, the occupation and…', 1812, NULL, NULL, 1997, NULL, NULL, 'year', '1812–1997', 39, 'https://en.wikipedia.org/wiki/Bessarabian_question'),
  ('Q2888462', 'Battle of Dragashani', 'The Battle of Drăgășani (or Dragashani) was fought on 19 June 1821 in Drăgășani, Wallachia, between the Ottoman forces of Sultan Mahmud II and the Greek Filiki Etaireia insurgents as a part of the Greek War of Independence.', 1821, 6, 7, NULL, NULL, NULL, 'day', '7 June 1821', 50, 'https://en.wikipedia.org/wiki/Battle_of_Dr%C4%83g%C4%83%C8%99ani'),
  ('Q258069', 'Battle of Segesvár', 'The Battle of Segesvár (Transylvania, now Sighișoara, Romania), also called the Battle of Fehéregyháza, was a battle in the Hungarian Revolution of 1848, fought on 31 July 1849 between the Hungarian revolutionary army under the command of Lieutenant General Józef Bem and the Russian V Corps under General Alexander von Lüders. The battle ended with the victory of the Russian army, which was presumably the death location of the Hungarian poet and national hero Sándor Petőfi, but his body was never found.', 1849, 7, 31, NULL, NULL, NULL, 'day', '31 July 1849', 43, 'https://en.wikipedia.org/wiki/Battle_of_Segesv%C3%A1r'),
  ('Q629187', 'Battle of Piski', 'The Battle of Piski was a battle in the Hungarian war of Independence of 1848-1849 fought on 9 February 1849 between the Hungarian army led by the Polish General Józef Bem and the Austrian army of the Habsburg Commander-in-Chief of Transylvania, Lieutenant General Anton Puchner. As a result of the defeats suffered by Bem against the much superior Austrian army, supported also by Romanian and Saxon militias, and a Russian army of several thousand soldiers, the Hungarian army was about to be pushed out of Transylvania.', 1849, 2, 9, NULL, NULL, NULL, 'day', '9 February 1849', 39, 'https://en.wikipedia.org/wiki/Battle_of_Piski'),
  ('Q1351343', 'Battle of Cetate', 'The Battle of Cetate was fought during the Crimean War. In this battle a large Ottoman force under Ahmed Pasha unsuccessfully attempted to capture the village of Cetate which was controlled by Russian Colonel Alexander Baumgarten.', 1853, 12, 31, 1854, 1, 6, 'day', '31 December 1853 – 6 January 1854', 41, 'https://en.wikipedia.org/wiki/Battle_of_Cetate'),
  ('Q174205', 'Tenth Russo-Turkish War', 'The Russo-Turkish War (1877–1878) was a conflict between the Ottoman Empire and a coalition led by the Russian Empire which included Romania, Serbia, and Montenegro. Precipitating factors included the Russian goals of recovering territorial losses endured during the Crimean War of 1853–1856, re-establishing itself in the Black Sea and supporting the political movement attempting to free Balkan nations from the Ottoman Empire.', 1878, 3, 3, 1878, 3, 3, 'day', '3 March 1878', 82, 'https://en.wikipedia.org/wiki/Russo-Turkish_War_(1877%E2%80%931878)'),
  ('Q1048169', 'Treaty of Berlin of 1878', 'The Treaty of Berlin (formally the Treaty between Austria-Hungary, France, Germany, Great Britain and Ireland, Italy, Russia, and the Ottoman Empire for the Settlement of Affairs in the East) was signed on 13 July 1878. In the aftermath of the Russian victory against the Ottoman Empire in the Russo-Turkish War of 1877–1878, the major powers restructured the map of the Balkan region.', 1878, 7, 13, NULL, NULL, NULL, 'day', '13 July 1878', 71, 'https://en.wikipedia.org/wiki/Treaty_of_Berlin_(1878)'),
  ('Q500067', 'Treaty of Bucharest', 'The Treaty of Bucharest (Romanian: Tratatul de la București; Serbian: Букурештански мир; Bulgarian: Букурещки договор; Greek: Συνθήκη του Βουκουρεστίου) was concluded on 10 August 1913, by the delegates of Bulgaria, Romania, Serbia, Montenegro and Greece. The Treaty was concluded in the aftermath of the Second Balkan War and amended the previous Treaty of London, which ended the First Balkan War.', 1913, 8, 10, NULL, NULL, NULL, 'day', '10 August 1913', 72, 'https://en.wikipedia.org/wiki/Treaty_of_Bucharest_(1913)'),
  ('Q2268427', 'Treaty of Bucharest', 'The Treaty of Bucharest of 1916 was signed between Romania and the Entente Powers on 4 (Old Style)/17 (New Style) August 1916 in Bucharest. The treaty stipulated the conditions under which Romania agreed to join the war on the side of the Entente, particularly territorial promises in Austria-Hungary.', 1916, 7, 27, NULL, NULL, NULL, 'day', '27 July 1916', 57, 'https://en.wikipedia.org/wiki/Treaty_of_Bucharest_(1916)'),
  ('Q2628859', 'Battle of Bucharest', 'The Battle of Bucharest, also known as the Argeş–Neajlov Defensive Operation in Romania, was the last battle of the Romanian Campaign of 1916 in World War I, in which the Central Powers'' combatants, led by General Erich von Falkenhayn, occupied the Romanian capital and forced the Romanian Government, as well as the remnants of the Romanian Army to retreat to Moldavia and re-establish its capital at Iaşi. The battle was of defensive nature, as the Romanian Army was joined by a part of the Imperial Russian army.', 1916, 12, 6, 1916, 12, 3, 'day', '6 December 1916 – 3 December 1916', 53, 'https://en.wikipedia.org/wiki/Battle_of_Bucharest'),
  ('Q2633083', 'Romanian Army offensive in Transylvania in 1916', 'The Battle of Transylvania was the first major operation of Romania during World War I, beginning on 27 August 1916. It started as an attempt by the Romanian Army to seize Transylvania, and potentially knock Austria-Hungary out of the war.', 1916, 10, 16, 1916, 11, 26, 'day', '16 October 1916 – 26 November 1916', 58, 'https://en.wikipedia.org/wiki/Battle_of_Transylvania'),
  ('Q3657549', 'Second Battle of Cobadin', 'The Second Battle of Cobadin took place from 19 to 25 October 1916 between the Central Powers, chiefly the Bulgarian Third Army, and the Entente, represented by the Russo–Romanian Dobruja Army. The battle ended in a decisive victory for the Central Powers; it resulted in the occupation of the strategic port of Constanța and the capture of the railway between that city and Cernavodă.', 1916, 10, 19, 1916, 10, 25, 'day', '19 October 1916 – 25 October 1916', 41, 'https://en.wikipedia.org/wiki/Second_Battle_of_Cobadin'),
  ('Q3921577', 'First Battle of Cobadin', 'The First Battle of Cobadin, also known as the First Battle of the Rasova–Cobadin–Tuzla Line, was fought from 17 to 19 of September 1916 between the Bulgarian Third Army and the Romanian–Russian Army of the Dobruja. The battle ended in Entente tactical victory and forced the Central Powers to hold their offensive and assume a defensive stance till the middle of October.', 1916, 9, 17, 1916, 9, 19, 'day', '17 September 1916 – 19 September 1916', 39, 'https://en.wikipedia.org/wiki/First_Battle_of_Cobadin'),
  ('Q4872831', 'Battle of the Argeş', 'The Battle of the Argeș took place during the Romanian Campaign of World War I on 1 December 1916. The battle was fought along the line of the Argeș River in Romania between Austro-German forces of the Central Powers and Romanian forces with the Russian imperial forces.', 1916, 12, 1, NULL, NULL, NULL, 'day', '1 December 1916', 43, 'https://en.wikipedia.org/wiki/Battle_of_the_Arge%C8%99'),
  ('Q2889252', 'Battle of Mărășești', 'The Battle of Mărășești (6 August 1917 – 3 September 1917) was the last major battle fought by the Central Powers against the Kingdom of Romania and Russia on the Romanian front during World War I. Romania was mostly occupied by the Central Powers, but the Battle of Mărășești kept the northern region of the country free from occupation.', 1917, 9, 3, 1917, 9, 8, 'day', '3 September 1917 – 8 September 1917', 53, 'https://en.wikipedia.org/wiki/Battle_of_M%C4%83r%C4%83%C8%99e%C8%99ti'),
  ('Q4087448', 'Battle of Mărăşti', 'The Battle of Mărăști (Romanian: Bătălia de la Mărăști) was one of the main battles to take place on Romanian soil in World War I. It was fought between 22 July and 1 August 1917, and was an offensive operation of the Romanian and Russian armies intended to encircle and destroy the German 9th Army. The operation was planned to occur in tandem with the Nămoloasa offensive; however, this operation was abandoned before it began.', 1917, 7, 22, 1917, 8, 1, 'day', '22 July 1917 – 1 August 1917', 47, 'https://en.wikipedia.org/wiki/Battle_of_M%C4%83r%C4%83%C8%99ti'),
  ('Q165755', 'Treaty of Bucharest', 'The Treaty of Bucharest (1918) was a peace treaty between Romania and the opposing Central Powers following the stalemate reached after the campaign of 1917. This left Romania isolated after Russia''s unilateral exit from World War I (see the Armistice of Focșani and Treaty of Brest-Litovsk).', 1918, 5, 7, NULL, NULL, NULL, 'day', '7 May 1918', 68, 'https://en.wikipedia.org/wiki/Treaty_of_Bucharest_(1918)'),
  ('Q1989779', 'Union of Transylvania with Romania', 'The union of Transylvania with Romania was declared on 1 December [O.S. 18 November] 1918 by the assembly of the delegates of ethnic Romanians held in Alba Iulia. Great Union Day, also called Unification Day, is a national holiday in Romania celebrated on 1 December.', 1918, 12, 1, NULL, NULL, NULL, 'day', '1 December 1918', 55, 'https://en.wikipedia.org/wiki/Union_of_Transylvania_with_Romania'),
  ('Q2292449', 'Treaty of Craiova', 'The Treaty of Craiova (Bulgarian: Крайовска спогодба, romanized: Krayovska spogodba; Romanian: Tratatul de la Craiova) was signed on 7 September 1940 and ratified on 13 September 1940 by the Kingdom of Bulgaria and the Kingdom of Romania. Under its terms, Romania ceded Southern Dobruja back to Bulgaria, which Romania had gained after the 1913 Second Balkan War.', 1940, 9, 7, NULL, NULL, NULL, 'day', '7 September 1940', 61, 'https://en.wikipedia.org/wiki/Treaty_of_Craiova'),
  ('Q2658524', '1940 Vrancea earthquake', 'The 1940 Vrancea earthquake, also known as the 1940 Bucharest earthquake, (Romanian: Cutremurul din 1940) occurred on Sunday, 10 November 1940, in Romania, at 03:39 (local time), when the majority of the population was at home. The 1940 earthquake registered a magnitude of 7.7 on the moment magnitude scale, being the strongest earthquake recorded in the 20th century in Romania.', 1940, 11, 10, NULL, NULL, NULL, 'day', '10 November 1940', 48, 'https://en.wikipedia.org/wiki/1940_Vrancea_earthquake'),
  ('Q700937', 'Crimean Campaign', 'The Crimean campaign was conducted by the Axis as part of Operation Barbarossa during World War II. The invading force was led by Germany with support from Romania and Italy, while the Soviet Union took up defensive positions throughout the Crimean Peninsula. The Axis offensive routed the Red Army and enabled the three-year-long German occupation of Crimea.', 1941, 10, 18, 1942, 7, 4, 'day', '18 October 1941 – 4 July 1942', 61, 'https://en.wikipedia.org/wiki/Crimean_campaign'),
  ('Q3376121', 'The Holocaust in Romania', 'The Holocaust saw the genocide of Jews in the Kingdom of Romania and in Romanian-controlled territories of the Soviet Union between 1940 and 1944. While historically part of The Holocaust, these actions were mostly independent from the similar acts committed by Nazi Germany, Romania being the only ally of the Third Reich that carried out a genocidal campaign without the intervention of Heinrich Himmler''s SS. Various numbers have been advanced by researchers for the lives lost in the genocide, with most estimates in the range of 250,000 to 380,000.', 1941, NULL, NULL, 1943, NULL, NULL, 'year', '1941–1943', 48, 'https://en.wikipedia.org/wiki/The_Holocaust_in_Romania'),
  ('Q18545517', 'Bucharest pogrom', 'Between 21 and 23 January 1941, a rebellion of the Iron Guard paramilitary organization, whose members were known as Legionnaires, occurred in Bucharest, Romania. As their privileges were being gradually removed by the Conducător Ion Antonescu, the Legionnaires revolted.', 1941, 1, 23, NULL, NULL, NULL, 'day', '23 January 1941', 52, 'https://en.wikipedia.org/wiki/Legionnaires''_rebellion_and_Bucharest_pogrom'),
  ('Q311765', 'Jassy–Kishinev Offensive', 'The Jassy–Kishinev offensive, named after the two major cities, Jassy and Kishinev, in the staging area, was a Soviet offensive against Axis forces, which took place in Eastern Romania from 20 to 29 August 1944 during World War II. The 2nd and 3rd Ukrainian Fronts of the Red Army engaged Army Group South Ukraine, which consisted of combined German and Romanian formations, in an operation to reoccupy Bessarabia and destroy the Axis forces in the region, opening the way into Romania and the Balkans. The offensive resulted in the encirclement and destruction of the German forces, allowing the…', 1944, 8, 29, 1944, 8, 29, 'day', '29 August 1944', 67, 'https://en.wikipedia.org/wiki/Second_Jassy%E2%80%93Kishinev_offensive'),
  ('Q4382262', 'First Battle of Târgu Frumos', 'The First Battle of Târgu Frumos was fought during World War II between Axis powers commanded by Otto Wöhler and Soviet forces led by Ivan Konev. Historian David Glantz has described it as part of a failed Soviet invasion of Romania, while Russian and German sources have described it as part of the Târgu Frumos Operation.', 1944, 4, 9, 1944, 4, 12, 'day', '9 April 1944 – 12 April 1944', 43, 'https://en.wikipedia.org/wiki/First_Battle_of_T%C3%A2rgu_Frumos'),
  ('Q4859251', 'Battle of Romania', 'The Battle of Romania in World War II comprised several operations in or around Romania in 1944, as part of the Eastern Front, in which the Soviet Army defeated Axis (German and Romanian) forces in the area, Romania changed sides, and Soviet and Romanian forces drove the Germans back into Hungary. Soviet troops entered Romanian territory during the Uman–Botoșani offensive in March 1944, capturing several towns in northern Moldavia, including Botoșani.', 1944, NULL, NULL, NULL, NULL, NULL, 'year', '1944', 47, 'https://en.wikipedia.org/wiki/Battle_of_Romania'),
  ('Q751139', '1977 Vrancea earthquake', 'The 1977 Vrancea earthquake occurred on 4 March 1977, at 21:22 local time, and was felt throughout the Balkans. It had a magnitude of 7.5, making it the second most powerful earthquake recorded in Romania in the 20th century, after the 10 November 1940 seismic event.', 1977, 3, 4, NULL, NULL, NULL, 'day', '4 March 1977', 62, 'https://en.wikipedia.org/wiki/1977_Vrancea_earthquake'),
  ('Q4115010', '1986 Vrancea earthquake', 'Striking central Romania on August 30 at 21:28 UTC, the 1986 Vrancea earthquake killed more than 150 people, injured over 500, and damaged over 50,000 homes. The second largest earthquake in the area since the modernization of earthquake monitoring devices, it was felt north to Poland and south to Italy and Greece.', 1986, 8, 30, NULL, NULL, NULL, 'day', '30 August 1986', 39, 'https://en.wikipedia.org/wiki/1986_Vrancea_earthquake'),
  ('Q204213', 'Romanian Revolution (1989)', 'The Romanian revolution (Romanian: Revoluția română) was a period of violent civil unrest in the Socialist Republic of Romania during December 1989 as a part of the revolutions of 1989 that occurred in several countries around the world, primarily within the Eastern Bloc. The Romanian revolution started in the city of Timișoara and soon spread throughout the country, ultimately culminating in the drumhead trial and execution of longtime Romanian Communist Party (PCR) General Secretary Nicolae Ceaușescu and his wife Elena, and the end of 42 years of Communist rule in Romania.', 1989, 12, 25, 1989, 12, 27, 'day', '25 December 1989 – 27 December 1989', 75, 'https://en.wikipedia.org/wiki/Romanian_revolution'),
  ('Q2368744', 'Golaniad', 'The Golaniad (Romanian: Golaniada pronounced [ɡolaniˈada], from the word golan meaning "hoodlum") was a protest in Romania in the University Square, Bucharest. It was initiated by students and professors at the University of Bucharest.', 1990, 4, 22, 1990, 6, 13, 'day', '22 April 1990 – 13 June 1990', 48, 'https://en.wikipedia.org/wiki/Golaniad'),
  ('Q3104871', 'TAROM Flight 371', 'TAROM Flight 371 was a scheduled international passenger flight from Otopeni International Airport in Romania''s capital Bucharest to Brussels Airport in Belgium. On 31 March 1995, the Airbus A310 operating flight 371 entered a steep turn and dive shortly after takeoff, crashing near Balotești in Romania, killing all 60 people on board.', 1995, 3, 31, NULL, NULL, NULL, 'day', '31 March 1995', 51, 'https://en.wikipedia.org/wiki/TAROM_Flight_371'),
  ('Q6271321', 'Mihăileşti explosion', 'This is a list of notable tank truck fires and explosions.', 2004, 5, 24, NULL, NULL, NULL, 'day', '24 May 2004', 43, 'https://en.wikipedia.org/wiki/Mih%C4%83ile%C8%99ti_explosion'),
  ('Q2721619', 'Romanian presidential impeachment referendum', 'A presidential impeachment referendum was held in Romania on 19 May 2007 in order to determine whether president Traian Băsescu should be forced to step down. On 19 April 2007 the Romanian parliament suspended Băsescu.', 2007, 5, 19, NULL, NULL, NULL, 'day', '19 May 2007', 41, 'https://en.wikipedia.org/wiki/2007_Romanian_presidential_impeachment_referendum'),
  ('Q28482411', '2017-2019 Romanian protests', 'There were numerous protests against the Romanian Government between 2017 and 2019. In January 2017, days after the government of the Grindeanu Cabinet was sworn into office in Romania, protests took place throughout the country against ordinance bills that were proposed by the Romanian Ministry of Justice regarding the pardoning of certain committed crimes, and the amendment of the Penal Code of Romania (especially regarding the abuse of power).', 2010, NULL, NULL, NULL, NULL, NULL, 'decade', '2010s', 60, 'https://en.wikipedia.org/wiki/2017%E2%80%932019_Romanian_protests'),
  ('Q948130', '2012 Romanian protests', 'The 2012 Romanian protests were a series of protests and civil manifestations triggered by the introduction of new health reform legislation. In particular, President Traian Băsescu criticized the Deputy Minister of Health, Raed Arafat, on a Romanian television broadcast.', 2012, NULL, NULL, NULL, NULL, NULL, 'year', '2012', 45, 'https://en.wikipedia.org/wiki/2012_Romanian_protests'),
  ('Q2617106', 'Romanian presidential impeachment referendum', 'A referendum on impeaching President Traian Băsescu was held in Romania on 29 July 2012. The referendum was required after Parliament voted in favour of impeaching Băsescu on 6 July, and had to take place within a month.', 2012, 7, 29, NULL, NULL, NULL, 'day', '29 July 2012', 41, 'https://en.wikipedia.org/wiki/2012_Romanian_presidential_impeachment_referendum'),
  ('Q16879871', '2014 Southeast Europe floods', 'Between 13 and 18 May 2014 a low-pressure cyclone designated Tamara and Yvette affected a large area of Southeastern and Central Europe, causing floods and landslides. Serbia and Bosnia and Herzegovina suffered the greatest damage, as the rain was the heaviest in 120 years of recorded weather measurements.', 2014, 5, 27, 2014, 5, 27, 'day', '27 May 2014', 63, 'https://en.wikipedia.org/wiki/2014_Southeast_Europe_floods'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods'),
  ('Q130297776', '2024 Central European floods', 'The 2024 Central European floods were a series of floods caused by a record heavy rainfall generated by Storm Boris, an extremely humid Genoa low. The flooding began in Austria and the Czech Republic, then spread to Poland, Romania and Slovakia, and then onwards to Germany and Hungary.', 2024, 9, NULL, NULL, NULL, NULL, 'month', 'September 2024', 57, 'https://en.wikipedia.org/wiki/2024_Central_European_floods');
